package com.bananalab.lite;
import android.content.*;import org.json.*;import java.util.*;import java.util.regex.*;import java.io.*;
/** Diagnostic/compile/test/retry workbench. Reuses only observed, applied, bounded repair rules. */
final class AndroidRepair{
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-android-repair",0);}
 static final class Solution{String original,body;JavaTextPlan plan;JSONArray attempts=new JSONArray();LinkedHashSet<String> rules=new LinkedHashSet<>();int tests;}
 static JSONArray cases(Context c)throws Exception{return new JSONArray(prefs(c).getString("cases","[]"));}
 static String[] order(Context c)throws Exception{final Map<String,Integer> count=new HashMap<>();for(String rule:RepairSyntax.RULES)count.put(rule,0);JSONArray all=cases(c);for(int i=0;i<all.length();i++){JSONArray used=all.getJSONObject(i).getJSONArray("rules");for(int j=0;j<used.length();j++){String rule=used.getString(j);if(count.containsKey(rule))count.put(rule,count.get(rule)+1);}}List<String> names=new ArrayList<>(Arrays.asList(RepairSyntax.RULES));Collections.sort(names,(a,b)->Integer.compare(count.get(b),count.get(a)));names.remove("semicolon");names.remove("final_null");names.add(0,"semicolon");names.add("final_null");return names.toArray(new String[0]);}
 static String summary(Throwable e){String x=e.getMessage();if(x==null)x=e.getClass().getSimpleName();return x.replaceAll("/[^ \\n:]+","archivo").substring(0,Math.min(1800,x.replaceAll("/[^ \\n:]+","archivo").length()));}
 static OnDeviceJava.Build build(Context c,String base,String body)throws Exception{Map<String,String> files=new LinkedHashMap<>();files.put("BananaBehavior.java",JavaPatchPolicy.BASE);files.put("ChatLanguagePatched.java",RepairSyntax.compileSource(base,body));return OnDeviceJava.compileSources(c,files);}
 static Solution solve(Context c,String body,boolean repair)throws Exception{RepairSyntax.tokens(body);String base=JavaMethodEditor.base(c);Solution result=new Solution();result.original=body;result.body=body;String[] order=order(c);for(int attempt=0;attempt<6;attempt++){JSONObject log=new JSONObject().put("attempt",attempt+1);String error="";boolean compiled=false,passed=false;try{JavaChat.phase("Android: compilando intento "+(attempt+1)+"…");OnDeviceJava.Build built=build(c,base,result.body);compiled=true;JavaTextPlan ref=RepairSyntax.reference(result.body);JavaChat.phase("Android: comprobando respuestas y controles…");android.os.Bundle proof=JavaTrial.text(c,built.jar,ref.json().toString(),ref.samples().length);result.tests=proof.getInt("samples");passed=true;result.plan=ref;
   // A value-equality test must reject the original == even if the VM interns a sample.
   if(!RepairSyntax.canonical(result.body).equals(result.body))throw new IllegalArgumentException("El cuerpo necesita comparación por valor o quitar llaves de un if simple para ajustarse al contrato.");
  }catch(Throwable failure){error=summary(failure);}
  log.put("compiled",compiled).put("passed",passed&&error.isEmpty()).put("diagnostic",error);result.attempts.put(log);if(error.isEmpty())return result;if(!repair)break;String next=RepairSyntax.next(result.body,result.rules,order);if(next.equals(result.body))break;result.body=next;}
  return result;
 }
 static synchronized String prepare(Context c,String body,boolean repair)throws Exception{if(repair&&!prefs(c).edit().remove("pending").commit())throw new IOException("No pude iniciar un intento nuevo.");int rev=JavaMethodEditor.prefs(c).getInt("revision",0);String originalActive=JavaMethodEditor.prefs(c).getString("active","");Solution result=solve(c,body,repair);JSONObject report=new JSONObject().put("target","ChatLanguage.java/socialReply").put("attempts",result.attempts).put("rules",new JSONArray(result.rules)).put("success",result.plan!=null&&result.attempts.getJSONObject(result.attempts.length()-1).optBoolean("passed"));if(!prefs(c).edit().putString("report",report.toString()).commit())throw new IOException("No pude guardar el diagnóstico.");if(!report.getBoolean("success"))return "Conservé el código activo. No encontré una reparación comprobada dentro del alcance.\n"+report.toString(2)+"\nNo se cambió el borrador del editor.";if(!repair)return "El cuerpo compila y pasó sus pruebas. No guardé ni activé un candidato.\n"+report.toString(2);
  if(JavaMethodEditor.prefs(c).getInt("revision",0)!=rev||!originalActive.equals(JavaMethodEditor.prefs(c).getString("active","")))throw new IOException("El método cambió durante el diagnóstico.");JavaMethodEditor.prepare(c,result.plan);String draft=JavaMethodEditor.prefs(c).getString("draft","");JSONObject pending=new JSONObject().put("draftHash",JavaMethodEditor.hash(draft)).put("before",body).put("after",result.body).put("rules",new JSONArray(result.rules)).put("attempts",result.attempts).put("tests",result.tests);if(!prefs(c).edit().putString("pending",pending.toString()).commit())throw new IOException("La copia probada quedó en el editor, pero no pude guardar su registro de reparación.");return "Preparé una reparación comprobada en Android.\nIntentos: "+result.attempts.length()+"; cambios de reparación: "+result.rules+"; pruebas: "+result.tests+".\nEl método activo se conserva. Pedí ‘ver reparacion android’, ‘aplica reparacion android’ o ‘descarta reparacion android’.";
 }
 static void applied(Context c,String activatedDraft){try{String pending=prefs(c).getString("pending","");if(pending.isEmpty())return;JSONObject p=new JSONObject(pending);if(!p.getString("draftHash").equals(JavaMethodEditor.hash(activatedDraft)))return;JSONArray all=cases(c),next=new JSONArray();for(int i=Math.max(0,all.length()-15);i<all.length();i++)next.put(all.getJSONObject(i));next.put(new JSONObject().put("rules",p.getJSONArray("rules")).put("beforeHash",JavaMethodEditor.hash(p.getString("before"))).put("afterHash",JavaMethodEditor.hash(p.getString("after"))).put("tests",p.getInt("tests")).put("acceptedRevision",JavaMethodEditor.prefs(c).getInt("revision",0)).put("source","compiled_tested_user_applied"));if(!prefs(c).edit().putString("cases",next.toString()).remove("pending").commit())throw new IOException("No pude guardar el caso aplicado.");}catch(Exception e){prefs(c).edit().putString("memoryError","El código se activó; no pude registrar el caso comprobado.").apply();}}
 static String search(Context c,String query)throws Exception{JSONArray index=new JSONObject(AppJavaChat.asset(c,"code-map.json",1500000)).getJSONArray("files");Set<String> words=AdaptiveMemory.terms(query);Map<String,String> hints=new LinkedHashMap<>();hints.put("personaj","ScenePlanner SceneDirector ScenePositions SceneConsistency");hints.put("borrador","CreatorSession CreatorMemory BananaProject");hints.put("respuesta","ChatLanguage BananaChat DialogueState MobileCore");hints.put("salto","Scene JavaFunction Motion");hints.put("guardar","SceneStore BananaProject");hints.put("audio","VoiceSynth VideoExporter");List<String[]> ranked=new ArrayList<>();for(int i=0;i<index.length();i++){JSONObject f=index.getJSONObject(i);String name=f.getString("name"),source=AppJavaChat.asset(c,"app-source/"+name,250000);int score=0;for(String word:words){if(source.toLowerCase(Locale.ROOT).contains(word))score++;for(String key:hints.keySet())if(word.contains(key)&&hints.get(key).contains(name.replace(".java","")))score+=4;}if(score>0){String snippet="";String[] lines=source.split("\n");int line=1;outer:for(int at=0;at<lines.length;at++)for(String word:words)if(lines[at].toLowerCase(Locale.ROOT).contains(word)){snippet=lines[at].trim();line=at+1;break outer;}ranked.add(new String[]{""+score,f.getString("path")+":"+line,snippet.substring(0,Math.min(220,snippet.length()))});}}Collections.sort(ranked,(a,b)->Integer.compare(Integer.parseInt(b[0]),Integer.parseInt(a[0])));StringBuilder out=new StringBuilder("Coincidencias en el código instalado (orientación por texto y nombres, no diagnóstico confirmado):");for(int i=0;i<Math.min(5,ranked.size());i++)out.append("\n").append(ranked.get(i)[1]).append("\n").append(ranked.get(i)[2]);return out.toString();}
 static String benchmark(Context c)throws Exception{String[] inputs={"if (text.equals(\"hola\")) return \"Buenas\"\nreturn null;","if (text.equal(\"hola\")) return \"Buenas\"; return null;","if (text.equals(\"hola\")) return \"Buenas\";","if (text == \"hola\") return \"Buenas\"; return null;"};int successes=0,total=0;JSONArray details=new JSONArray();String active=JavaMethodEditor.prefs(c).getString("active",""),draft=JavaMethodEditor.prefs(c).getString("draft","");for(String input:inputs){Solution s=solve(c,input,true);boolean ok=s.attempts.length()>0&&s.attempts.getJSONObject(s.attempts.length()-1).optBoolean("passed");total++;if(ok)successes++;details.put(new JSONObject().put("task",total).put("passed",ok).put("attempts",s.attempts.length()));}if(!active.equals(JavaMethodEditor.prefs(c).getString("active",""))||!draft.equals(JavaMethodEditor.prefs(c).getString("draft","")))throw new IOException("El evaluador modificó el editor inesperadamente.");String report="Evaluación Android: "+successes+"/"+total+" reparaciones comprobadas.\n"+details.toString(2)+"\nTareas sintéticas de regresión, no un examen de programación general ni tareas nunca vistas por estas reglas. No activé cambios.";prefs(c).edit().putString("benchmark",report).commit();return report;}
 static BananaEngine.Result handle(Context c,String message)throws Exception{String q=ChatLanguage.normalize(message);if(q.equals("programador android"))return MobileCore.say(c,"Programador Android · diagnóstico, compilación, pruebas y reparación acotada.\n‘Repara mi ultimo cambio’ usa el último intento escrito del método del chat.\n‘Repara metodo del chat: if (text.equal(\"hola\")) return \"Buenas\"; return null;’\n‘Ver reparacion android’, ‘aplica reparacion android’, ‘descarta reparacion android’.\n‘Busca en el codigo: segundo personaje no aparece’ orienta hacia archivos con evidencia.\n‘Evalua programador android’ comprueba cuatro errores conocidos sin cambiar el editor.\nNo genera Java general ni entrena un modelo programador nuevo.","app_ajuste");if(q.startsWith("busca en el codigo ")){int at=message.indexOf(':');String query=at>=0?message.substring(at+1).trim():message.substring("busca en el codigo ".length()).trim();return MobileCore.say(c,search(c,query),"app_ajuste");}
  boolean last=q.matches("repara mi ultimo cambio|diagnostica mi ultimo cambio"),repair=q.startsWith("repara");if(last||q.startsWith("repara metodo del chat")||q.startsWith("diagnostica metodo del chat")){String raw=last?JavaMethodEditor.prefs(c).getString("lastInput",""):message;int at=raw.indexOf(':');if(at<0)return MobileCore.say(c,"No hay un cuerpo de método escrito para revisar. Pedí ‘programador android’ para ver un ejemplo.","app_ajuste");String prefix=ChatLanguage.normalize(raw.substring(0,at));if(!prefix.matches("repara metodo del chat|diagnostica metodo del chat|reescribe el metodo del chat"))return MobileCore.say(c,"El reparador necesita el cuerpo del método del chat. No voy a inventar un cambio para otra parte de la app.","app_ajuste");JavaChat.owner=Thread.currentThread();try{return MobileCore.say(c,prepare(c,raw.substring(at+1).trim(),repair),"app_ajuste");}catch(Exception e){prefs(c).edit().putString("report",new JSONObject().put("success",false).put("diagnostic",summary(e)).toString()).apply();return MobileCore.say(c,"Conservé el método activo: "+summary(e),"app_ajuste");}finally{JavaChat.owner=null;JavaChat.progress="";}}
  if(q.equals("ver diagnostico android"))return MobileCore.say(c,prefs(c).getString("report","No hay un diagnóstico."),"app_ajuste");if(q.equals("ver reparacion android")){String pending=prefs(c).getString("pending","");return MobileCore.say(c,pending.isEmpty()?prefs(c).getString("report","No hay una reparación registrada."):"ANTES:\n"+new JSONObject(pending).getString("before")+"\nDESPUÉS:\n"+new JSONObject(pending).getString("after")+"\nIntentos de este candidato:\n"+new JSONObject(pending).getJSONArray("attempts").toString(2),"app_ajuste");}
  if(q.equals("aplica reparacion android")){String pending=prefs(c).getString("pending","");if(pending.isEmpty())return MobileCore.say(c,"No hay una reparación probada pendiente.","app_ajuste");if(!new JSONObject(pending).getString("draftHash").equals(JavaMethodEditor.hash(JavaMethodEditor.prefs(c).getString("draft",""))))return MobileCore.say(c,"El borrador cambió; prepará la reparación otra vez.","app_ajuste");try{return MobileCore.say(c,JavaMethodEditor.apply(c),"app_ajuste");}catch(Exception e){return MobileCore.say(c,"No activé la reparación: "+summary(e),"app_ajuste");}}
  if(q.equals("descarta reparacion android")){String pending=prefs(c).getString("pending","");if(!pending.isEmpty()&&new JSONObject(pending).getString("draftHash").equals(JavaMethodEditor.hash(JavaMethodEditor.prefs(c).getString("draft",""))))JavaMethodEditor.prefs(c).edit().remove("draft").commit();prefs(c).edit().remove("pending").commit();return MobileCore.say(c,"Descarté la reparación pendiente. El método activo se conserva.","app_ajuste");}
  if(q.equals("casos del programador android"))return MobileCore.say(c,"Arreglos compilados, probados y aplicados por vos: "+cases(c).length()+"\nOrden de reparaciones reutilizables: "+Arrays.toString(order(c))+"\n"+prefs(c).getString("memoryError","")+"\nEste registro prioriza reglas conocidas; no convierte al sistema en un programador general.","app_ajuste");if(q.equals("evalua programador android")){JavaChat.owner=Thread.currentThread();try{return MobileCore.say(c,benchmark(c),"app_ajuste");}finally{JavaChat.owner=null;JavaChat.progress="";}}return null;
 }
}
